from html import escape
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]


def answer_field(number, prompt, answer):
    return f'''<label class="question-row"><strong>{number}.</strong><span>{prompt}</span><input type="text" data-answer="{escape(answer, quote=True)}" data-main-answer="true" autocomplete="off"></label>'''


def exercise(title, instruction, fields, extra=""):
    return f'''<section class="exercise-block"><h3>{title}</h3><p><strong>{instruction}</strong></p>{extra}<form data-reading-form>{''.join(fields)}<div class="actions"><button class="btn green" type="button" data-check-reading>Kiểm tra</button><button class="btn" type="reset" data-reset-reading>Làm lại</button></div><div class="result" data-reading-result></div></form></section>'''


def solution(number, answer, qtype, question_vi, analysis, evidence, paraphrase, detail):
    return f'''<article class="solution-card"><h4>Question {number} / Answer: <span>{escape(answer)}</span></h4><dl><dt>Loại câu hỏi</dt><dd>{qtype}</dd><dt>Dịch nghĩa</dt><dd>{question_vi}</dd><dt>Phân tích</dt><dd>{analysis}</dd><dt>Đoạn chứa thông tin</dt><dd><mark>{evidence}</mark></dd><dt>Từ khóa paraphrase</dt><dd>{paraphrase}</dd><dt>Giải thích chi tiết</dt><dd>{detail}</dd></dl></article>'''


def vocab_table(rows):
    body=[]
    key=[]
    for row in rows:
        if len(row) == 4:
            sentence, phrase, word_type, meaning = row
        else:
            sentence, phrase, meaning = row
            word_type = "word / phrase"
        sentence_html=escape(sentence)
        start=sentence.lower().find(phrase.lower())
        if start >= 0:
            end=start+len(phrase)
            sentence_html=escape(sentence[:start])+f'<mark class="vocab-highlight">{escape(sentence[start:end])}</mark>'+escape(sentence[end:])
        body.append(f'''<tr><td>{sentence_html}</td><td>{escape(phrase)}</td><td><input class="source-answer-input" type="text" data-answer="{escape(word_type,quote=True)}" autocomplete="off" aria-label="Loại từ của {escape(phrase,quote=True)}"></td><td><input class="source-answer-input" type="text" data-answer="{escape(meaning,quote=True)}" autocomplete="off" aria-label="Nghĩa của {escape(phrase,quote=True)}"></td></tr>''')
        key.append(f'''<tr><td>{sentence_html}</td><td>{escape(phrase)}</td><td class="answer-reference">{escape(word_type)}</td><td class="answer-reference">{escape(meaning)}</td></tr>''')
    controls='''<div class="action-row"><button class="btn green" type="button" data-check-text>Kiểm tra</button><button class="btn ghost" type="reset" data-reset-text>Làm lại</button><span class="result" data-text-result></span></div>'''
    head='''<thead><tr><th>Sentences</th><th>Useful words/phrases</th><th>Type of word<br>(n/ v/ adj/ adv...)</th><th>Meaning<br>(in English/ in Vietnamese)</th></tr></thead>'''
    return f'''<section class="reference-task"><div class="source-table-title">New vocabulary</div><form data-text-form><div class="source-table-wrap"><table class="source-entry-table vocabulary-source-table">{head}<tbody>{''.join(body)}</tbody></table></div>{controls}</form><details class="answer-key-collapse collapse" data-section="vocabulary-answer-key"><summary>Xem đáp án New vocabulary</summary><div class="collapse-body source-table-wrap"><table class="source-entry-table vocabulary-source-table">{head}<tbody>{''.join(key)}</tbody></table></div></details></section>'''


def keyword_table(rows):
    body=[]
    key=[]
    for keyword, answer in rows:
        accepted=answer.replace(" / ","|")
        body.append(f'''<tr><td>{escape(keyword)}</td><td><input class="source-answer-input" type="text" data-answer="{escape(accepted,quote=True)}" autocomplete="off" aria-label="Similar words for {escape(keyword,quote=True)}"></td></tr>''')
        key.append(f'''<tr><td>{escape(keyword)}</td><td class="answer-reference">{escape(answer)}</td></tr>''')
    controls='''<div class="action-row"><button class="btn green" type="button" data-check-text>Kiểm tra</button><button class="btn ghost" type="reset" data-reset-text>Làm lại</button><span class="result" data-text-result></span></div>'''
    head='''<thead><tr><th>Keywords in the questions</th><th>Similar words in the passage</th></tr></thead>'''
    return f'''<section class="reference-task"><div class="source-table-title">Keyword table</div><form data-text-form><div class="source-table-wrap"><table class="source-entry-table keyword-source-table">{head}<tbody>{''.join(body)}</tbody></table></div>{controls}</form><details class="answer-key-collapse collapse" data-section="keyword-answer-key"><summary>Xem đáp án Keyword table</summary><div class="collapse-body source-table-wrap"><table class="source-entry-table">{head}<tbody>{''.join(key)}</tbody></table></div></details></section>'''


def shell(number, title, source, work, link, filename):
    link_html=f'''<p class="external-reading">Read the passage in the following <a class="inline-link" href="{link}" target="_blank" rel="noopener">LINK</a> carefully, remember the meaning of the vocabulary in yellow and note down at least 10 new/useful words or phrases.</p><textarea class="notes-area" aria-label="Ghi ít nhất 10 từ mới"></textarea>'''
    html=f'''<!doctype html><html lang="vi"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{title}</title><link rel="stylesheet" href="styles.css?v=13"></head><body class="lesson-page"><div class="shell"><header class="topbar compact-topbar"><a class="back" href="index.html">← Quay lại danh sách</a><div class="title-wrap"><div><div class="eyebrow">FOUNDATION B • IELTS READING</div><h1 class="lesson-heading">{title}</h1></div><div class="original-top-actions"><button class="original-report-btn" type="button">Báo lỗi</button><a class="original-back-btn" href="index.html">← Quay lại</a></div><span class="lesson-badge">Bài số {number}</span></div></header><main class="lesson-grid"><section class="panel"><h2>Đề bài</h2><div class="panel-body reading-source font-safe">{source}{link_html}</div></section><section class="panel"><h2>Bài làm</h2><div class="panel-body reading-work font-safe">{work}</div></section></main></div><script src="app.js?v=12"></script></body></html>'''
    (ROOT/filename).write_text(html,encoding="utf-8")


# LESSON 11
source11='''<div class="original-reading-heading"><span class="reading-word">READING</span> <span class="reading-pass-label">READING PASSAGE 1</span></div><article class="reading-passage-card"><h3>PEDESTRIANS ONLY</h3><p class="subtitle">How traffic-free shopping streets developed</p>
<p><strong>A.</strong> The concept of traffic-free shopping areas goes back a long time. During the Middle Ages, traffic-free shopping areas known as souks were built in Middle Eastern countries to allow people to shop in comfort and, more importantly, safety. As far back as 2,000 years ago, road traffic was banned from central Rome during the day to allow for the free movement of pedestrians, and was only allowed in at night when shops and markets had closed for the day. In most other cities, however, pedestrians were forced to share the streets with horses, coaches and, later, with cars and other motorised vehicles.</p>
<p><strong>B.</strong> The modern, traffic-free shopping street was born in Europe in the 1960s, when both city populations and car ownership increased rapidly. Dirty exhaust fumes from cars and the risks involved in crossing the road were beginning to make shopping an unpleasant and dangerous experience. Many believed the time was right for experimenting with car-free streets, and shopping areas seemed the best place to start.</p>
<p><strong>C.</strong> At first, there was resistance from shopkeepers. They believed that such a move would be bad for business. They argued that people would avoid streets if they were unable to get to them in their cars. When the first streets in Europe were closed to traffic, there were even noisy demonstrations, as many shopkeepers predicted they would lose customers.</p>
<p><strong>D.</strong> However, research carried out afterwards in several European cities revealed some unexpected statistics. In Munich, Cologne and Hamburg, visitors to shopping areas increased by 50 per cent. On Copenhagen's main shopping street, shopkeepers reported sales increases of 25–40 per cent. Shopkeepers in Minneapolis, USA, were so impressed when they learnt this that they even offered to pay for the construction and maintenance costs of their own traffic-free streets.</p>
<p><strong>E.</strong> With the arrival of the traffic-free shopping street, many shops, especially those selling things like clothes, food and smaller luxury items, prospered. Unfortunately, it wasn't good news for everyone, as shops selling furniture and larger electrical appliances actually saw their sales drop. Many of these were forced to move elsewhere, away from the city centre. Today they are a common feature on the outskirts of towns and cities, often situated in out-of-town retail zones with their own car parks and other local facilities.</p></article>
<div class="original-reading-heading"><span class="reading-pass-label">READING PASSAGE 2</span></div><article class="reading-passage-card"><h3>AIR TRAFFIC CONTROL IN THE USA</h3>
<p><strong>A.</strong> An accident that occurred in the skies over the Grand Canyon in 1956 resulted in the establishment of the Federal Aviation Administration (FAA) to regulate and oversee the operation of aircraft in the skies over the United States, which were becoming quite congested. The resulting structure of air traffic control has greatly increased the safety of flight in the United States, and similar air traffic control procedures are also in place over much of the rest of the world.</p>
<p><strong>B.</strong> Rudimentary air traffic control (ATC) existed well before the Grand Canyon disaster. As early as the 1920s, the earliest air traffic controllers manually guided aircraft in the vicinity of the airports, using lights and flags, while beacons and flashing lights were placed along cross-country routes to establish the earliest airways. However, this purely visual system was useless in bad weather, and, by the 1930s, radio communication was coming into use for ATC. The first region to have something approximating today's ATC was New York City, with other major metropolitan areas following soon after.</p>
<p><strong>C.</strong> In the 1940s, ATC centres could and did take advantage of the newly developed radar and improved radio communication brought about by the Second World War, but the system remained rudimentary. It was only after the creation of the FAA that full-scale regulation of America's airspace took place, and this was fortuitous, for the advent of the jet engine suddenly resulted in a large number of very fast planes, reducing pilots' margin of error and practically demanding some set of rules to keep everyone well separated and operating safely in the air.</p>
<p><strong>D.</strong> Many people think that ATC consists of a row of controllers sitting in front of their radar screens at the nation's airports, telling arriving and departing traffic what to do. This is a very incomplete part of the picture. The FAA realised that the airspace over the United States would at any time have many different kinds of planes, flying for many different purposes, in a variety of weather conditions, and the same kind of structure was needed to accommodate all of them.</p>
<p><strong>E.</strong> To meet this challenge, the following elements were put into effect. First, ATC extends over virtually the entire United States. In general, from 365m above the ground and higher, the entire country is blanketed by controlled airspace. In certain areas, mainly near airports, controlled airspace extends down to 215m above the ground, and, in the immediate vicinity of an airport, all the way down to the surface. Controlled airspace is that airspace in which FAA regulations apply. Elsewhere, in uncontrolled airspace, pilots are bound by fewer regulations. In this way the recreational pilot who simply wishes to go flying for a while can easily avoid the controlled airspace.</p>
<p><strong>F.</strong> The FAA then recognised two types of operating environments. In good meteorological conditions, flying would be permitted under Visual Flight Rules (VFR), which suggests a strong reliance on visual cues to maintain an acceptable level of safety. Poor visibility necessitated a set of Instrumental Flight Rules (IFR), under which the pilot relied on altitude and navigational information provided by the plane's instrument panel to fly safely. On a clear day, a pilot in controlled airspace can choose a VFR or IFR flight plan, and the FAA regulations were devised in a way which accommodates both VFR and IFR operations in the same airspace. However, a pilot can only choose to fly IFR if they possess an instrument rating which is above and beyond the basic pilot's license that must also be held.</p>
<p><strong>G.</strong> Controlled airspace is divided into several different types, designated by letters of the alphabet. Uncontrolled airspace is designated Class F, while controlled airspace below 5,490m above sea level and not in the vicinity of an airport is Class E. All airspace above 5,490m is designated Class A. The reason for the division of Class E and Class A airspace stems from the type of planes operating in them. Generally, Class E airspace is where one finds general aviation aircraft (few of which can climb above 5,490m anyway), and commercial turboprop aircraft. Above 5,490m is the realm of the heavy jets, since jet engines operate more efficiently at higher altitudes. The difference between Class E and A airspace is that in Class A, all operations are IFR, and pilots must be instrument-rated, that is, skilled and licensed in aircraft instrumentation. This is because ATC control of the entire space is essential. Three other types of airspace, Classes D, C and B, govern the vicinity of airports. These correspond roughly to small municipal, medium-sized metropolitan and major metropolitan airports respectively, and encompass an increasingly rigorous set of regulations. For example, all a VFR pilot has to do to enter Class C airspace is establish two-way radio contact with ATC. No explicit permission from ATC to enter is needed, although the pilot must continue to obey all regulations governing VFR flight. To enter Class B airspace, such as on approach to a major metropolitan airport, an explicit ATC clearance is required. The private pilot who cruises without permission into this airspace risks losing their license.</p></article>'''
