sol16=[]
facts=[("1 — Exercise 1","D","John Loud đã làm gì?","John Loud ... invented a pen with a reservoir of ink and a rolling ball.","invented first rolling-ball pen ↔ invented a pen ... rolling ball"),("2 — Exercise 1","B","Ladislas Biro đã làm gì?","He thought he spent too much time filling his pens ... decided to invent a better kind.","make job easier ↔ spent too much time / better pen"),("3 — Exercise 1","E","Augustine Justo đã làm gì?","Justo invited him to set up a factory in Argentina.","asked someone to start a business ↔ invited him to set up a factory"),("4 — Exercise 1","A","Milton Reynolds đã làm gì?","Milton Reynolds introduced the ballpoint pen to the USA and produced the Gimbels version.","sold first in North America ↔ introduced to USA"),("5 — Exercise 1","C","Patrick Frawley đã làm gì?","Papermates were selling in their millions around the world.","international success ↔ millions around the world"),("1 — Exercise 2","B","Vì sao người ta tới Gimbels?","The advertisement described the pen as fantastic and miraculous.","told how good ↔ advertisement described"),("2 — Exercise 2","D","Vì sao bút đời đầu không được sản xuất thương mại?","Thin ink leaked; thick ink did not come out at all.","didn't work properly ↔ leaked / did not come out"),("3 — Exercise 2","C","Điểm nào khiến bút Biro tốt hơn?","It didn't leak when the pen wasn't being used.","ink stayed in until needed ↔ didn't leak when unused"),("4 — Exercise 2","B","Bút thương mại đầu tiên của Biro có đặc điểm gì?","The pen needed to be held in a vertical position for the ink to come out.","used in a certain way ↔ held vertically"),("5 — Exercise 2","A","Bút của Patrick Frawley như thế nào?","Patrick Frawley improved the design.","better version ↔ improved design"),("1 — Japan","B","Sách toán Nhật Bản như thế nào?","Textbooks were well set out and logically developed.","well organised ↔ well set out / logically developed"),("2 — Japan","C","Chủ đề toán mới được giới thiệu thế nào?","The teacher explains the topic slowly and with repetition and elaboration.","carefully and patiently ↔ slowly / repetition / elaboration"),("3 — Japan","A","Nhà trường hỗ trợ học sinh gặp khó khăn thế nào?","Teachers give individual help ... extra work ... Juku if extra help is needed.","supplementary tuition ↔ individual help / Juku"),("4 — Japan","C","Vì sao thành tích toán cao?","The emphasis is on hard work coupled with a focus on accuracy.","much effort ↔ hard work; correct answers ↔ accuracy")]
